// app/members/page.tsx
"use client";

import React, { useEffect, useState } from "react";

type Member = {
  _id: string;
  name: string;
  description: string;
  tags: string[];
  avatar: string;
  blog: boolean;
  createdAt: string;
  updatedAt: string;
};

export default function MembersPage() {
  const [members, setMembers] = useState<Member[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  const BASE_URL = process.env.NEXT_PUBLIC_API_URL || "http://localhost:5000";

  const loadMembers = async () => {
    setIsLoading(true);
    try {
      const res = await fetch(`${BASE_URL}/api/members`);
      if (!res.ok) throw new Error("Failed to fetch members");
      const data = await res.json();
      setMembers(data.sort((a, b) => new Date(a.createdAt).getTime() - new Date(b.createdAt).getTime()));
    } catch (error) {
      console.error("Failed to fetch members", error);
      setMembers([]);
    }
    setIsLoading(false);
  };

  useEffect(() => {
    loadMembers();
  }, []);

  return (
    <div className="min-h-screen bg-gray-900 text-white p-8">
      <h1 className="text-3xl font-bold mb-6">Members</h1>
      {isLoading ? (
        <p>Loading members...</p>
      ) : members.length === 0 ? (
        <p>No members yet.</p>
      ) : (
        <ul className="space-y-4">
          {members.map((member) => (
            <li key={member._id} className="border p-4 rounded bg-gray-800">
              <h2 className="text-xl font-semibold">{member.name}</h2>
              <p>{member.description}</p>
              {member.tags.length > 0 && (
                <p className="mt-2 text-sm text-gray-400">Tags: {member.tags.join(", ")}</p>
              )}
              {member.blog && <p className="text-green-400 mt-1">Has Blog</p>}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
